/**
 * Model Item
 * 
 */
export type Item = $Result.DefaultSelection<Prisma.$ItemPayload>
/**
 * Model WorldviewSetting
 * 世界观与体系设定实体（灵气/斗气等能量体系、境界等级、组织势力、规则法则）。
 */
export type WorldviewSetting = $Result.DefaultSelection<Prisma.$WorldviewSettingPayload>
/**
 * Model CharacterReview
 * 
 */
export type CharacterReview = $Result.DefaultSelection<Prisma.$CharacterReviewPayload>
/**
 * Model ExtractionSession
 * 提取运行批次。一本书同时最多一个活动运行，由迁移中的部分唯一索引
 * ExtractionSession_book_active_unique（status IN 活动态时 bookId 唯一）约束。
 */
export type ExtractionSession = $Result.DefaultSelection<Prisma.$ExtractionSessionPayload>
/**
 * Model Task
 * 
 */
export type Task = $Result.DefaultSelection<Prisma.$TaskPayload>
/**
 * Model NoiseOverride
 * 文本清洗的人工覆盖：标记某行被“找回”（不删除）。lineNum 为规范化后文本 1-based 行号。
 */
export type NoiseOverride = $Result.DefaultSelection<Prisma.$NoiseOverridePayload>
/**
 * Model EntityImage
 * 实体图片元数据；文件名只使用 UUID，entityName 不进入文件路径。
 */
export type EntityImage = $Result.DefaultSelection<Prisma.$EntityImagePayload>
/**
 * Model VisualSpec
 * 可被下游钉死引用的视觉规格：prompt + 变体键 + 版本 + 主图。
 * 稳定键是 bookId+entityType+entityName+variantKey，重提只 SUPERSEDE 不删历史。
 */
export type VisualSpec = $Result.DefaultSelection<Prisma.$VisualSpecPayload>
/**
 * Model RefreshSession
 * 
 */
export type RefreshSession = $Result.DefaultSelection<Prisma.$RefreshSessionPayload>
/**
 * Model BackgroundJob
 * 
 */
export type BackgroundJob = $Result.DefaultSelection<Prisma.$BackgroundJobPayload>
/**
 * Model AuditLog
 * 
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model AssetObject
 * 不可变对象：内容寻址（sha256+bytes 唯一），objectKey 私有且不可覆盖。跨书籍去重。
 */
export type AssetObject = $Result.DefaultSelection<Prisma.$AssetObjectPayload>
/**
 * Model AssetSnapshot
 * 资产快照：版本化、不可变（ready 后不可改）。新表统一用 ownerId 语义（ADR 0001）。
 */
export type AssetSnapshot = $Result.DefaultSelection<Prisma.$AssetSnapshotPayload>
/**
 * Model SnapshotObject
 * 快照与对象的引用关系；logicalPath 为 ZIP 内逻辑路径，唯一 per 快照。
 * state 限定 present/empty/not-generated；对象是否可删除由引用关系事务计算。
 */
export type SnapshotObject = $Result.DefaultSelection<Prisma.$SnapshotObjectPayload>
/**
 * Model BookShare
 * 指定账号分享：active→copying→copied 或 active→revoked（条件更新，先成功者决定）。
 */
export type BookShare = $Result.DefaultSelection<Prisma.$BookSharePayload>
/**
 * Model BookArtifact
 * 书籍文件型产物登记（提取/故事/导演/run-summary 等）：(bookId, logicalPath) 唯一，
 * objectKey 指向对象存储；多设备经此表定位产物，不再扫描本机 output/。
 */
export type BookArtifact = $Result.DefaultSelection<Prisma.$BookArtifactPayload>
/**
 * Model PublicAsset
 * 公共素材：实体卡的不可变快照。payload 自包含，不依赖源书/源实体存活。
 * publisherId/takerId/targetBookId 均为裸列（无 FK），避免删用户/删书级联影响公共池。
 */
export type PublicAsset = $Result.DefaultSelection<Prisma.$PublicAssetPayload>
/**
 * Model PublicAssetImage
 * 公共素材的图片引用：字节不复制，指向 AssetObject（内容寻址）。
 * objectKey 冗余存储便于直接签 URL；AssetObject 行保证对象不被引用计数回收。
 */
export type PublicAssetImage = $Result.DefaultSelection<Prisma.$PublicAssetImagePayload>
/**
 * Model PublicAssetTake
 * 拿取记录：计数、防重复拿取提示、后续"我的拿取"列表。
 */
export type PublicAssetTake = $Result.DefaultSelection<Prisma.$PublicAssetTakePayload>
/**
 * Model EntityReview
 * 统一审核历史：四类实体（character | location | item | worldview）的创建/编辑/通过/拒绝/合并等动作记录。
 * 旧 CharacterReview 保留一个兼容周期并双写。
 */
export type EntityReview = $Result.DefaultSelection<Prisma.$EntityReviewPayload>
/**
 * Model AiUsageRecord
 * 模型调用账本：按用户/书籍/运行记录每次模型调用的用量与状态，不做价格配置。
 */
export type AiUsageRecord = $Result.DefaultSelection<Prisma.$AiUsageRecordPayload>

